ALTER TABLE public.services ADD COLUMN imported_requires_review boolean NOT NULL DEFAULT false;
UPDATE public.services SET imported_requires_review=true WHERE id IN(SELECT service_id FROM public.imported_client_visits) AND price=0;
CREATE FUNCTION public.review_imported_service() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF TG_OP='INSERT' THEN RETURN NEW; END IF; IF NEW.price IS DISTINCT FROM OLD.price OR NEW.duration_min IS DISTINCT FROM OLD.duration_min THEN NEW.imported_requires_review:=false; END IF; RETURN NEW; END $$;
CREATE TRIGGER review_imported_service BEFORE UPDATE ON public.services FOR EACH ROW EXECUTE FUNCTION public.review_imported_service();
CREATE FUNCTION public.prevent_unreviewed_service_booking() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF EXISTS(SELECT 1 FROM public.services WHERE id=NEW.service_id AND imported_requires_review) AND (TG_OP='INSERT' OR NEW.service_id IS DISTINCT FROM OLD.service_id) THEN RAISE EXCEPTION 'Revise preço e duração do serviço importado antes de agendar'; END IF; RETURN NEW; END $$;
CREATE TRIGGER a_review_imported_booking BEFORE INSERT OR UPDATE ON public.appointments FOR EACH ROW EXECUTE FUNCTION public.prevent_unreviewed_service_booking();
DO $$ DECLARE def text; BEGIN SELECT pg_get_functiondef('public.import_salon_clients(uuid,jsonb)'::regprocedure) INTO def; def:=replace(def,'INSERT INTO public.services(salon_id,name,price,duration_min) VALUES(_salon,trim(r->>''service''),0,60)','INSERT INTO public.services(salon_id,name,price,duration_min,imported_requires_review) VALUES(_salon,trim(r->>''service''),0,60,true)'); EXECUTE def; END $$;
CREATE FUNCTION public.appointment_return_forecast(_salon uuid,_service uuid,_phone text,_date date) RETURNS date LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE s public.services; c uuid; t public.service_return_targets; n integer; BEGIN IF NOT public.manages_salon(_salon) THEN RAISE EXCEPTION 'Acesso restrito'; END IF; SELECT * INTO s FROM public.services WHERE id=_service AND salon_id=_salon; IF NOT FOUND THEN RETURN NULL; END IF; SELECT id INTO c FROM public.salon_clients WHERE salon_id=_salon AND right(regexp_replace(whatsapp,'[^0-9]','','g'),11)=right(regexp_replace(_phone,'[^0-9]','','g'),11) AND length(regexp_replace(_phone,'[^0-9]','','g'))>=10 ORDER BY id LIMIT 1; SELECT * INTO t FROM public.service_return_targets WHERE salon_id=_salon AND client_id=c AND service_id=_service; n:=s.intervalo_retorno_dias; IF s.regra_cliente='progressiva' AND coalesce(t.visits,0)+1>3 AND _date>(t.first_visit+interval '3 months')::date THEN n:=s.intervalo_cliente_antiga_dias; END IF; RETURN _date+n; END $$;
REVOKE ALL ON FUNCTION public.appointment_return_forecast(uuid,uuid,text,date) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.appointment_return_forecast(uuid,uuid,text,date) TO authenticated;